-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 19
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 19 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Avaliação Prática', 'PENDENTE', v_aula, 'Atividade — Avaliação Prática (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/AVALIACAO-PRATICA.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina o que é design (planejamento intencional de forma e função para resolver uma necessidade humana concreta).', 0.1, 'Design é o planejamento intencional da forma e da função de um produto para resolver uma necessidade humana concreta; não é decoração, pois toda escolha visual serve a um propósito de uso.', 'Nota cheia: definição com planejamento intencional + forma e função + necessidade humana. Metade: definição incompleta (só "deixar bonito" corrigido de forma vaga). Zero: confunde design com enfeite.'),
      (v_atividade, 1, 2, 'Explique por que "tela bonita" sem função não resolve a necessidade do paciente no agendamento.', 0.2, 'Uma tela bonita que não resolve a tarefa (marcar, remarcar, cancelar sem ligar) falha na função: o paciente continua dependendo da recepção. Estética sem função é decoração; o design existe para remover a barreira entre a pessoa e o objetivo dela.', 'Nota cheia: liga a falha à função não cumprida no caso do agendamento. Metade: fala que "bonito não basta" sem ligar ao caso. Zero: defende que só a estética importa.'),
      (v_atividade, 1, 3, 'Relacione forma e função num exemplo concreto dentro do projeto de agendamento.', 0.2, 'Exemplo coerente, ex.: o botão "Agendar" (forma: grande, destacado, texto claro) existe para a função de marcar consulta; se o botão é bonito mas some na tela, a forma falhou com a função.', 'Nota cheia: exemplo concreto do agendamento ligando forma à função. Metade: exemplo genérico ou sem a ligação forma↔função. Zero: sem exemplo.'),
      (v_atividade, 2, 1, 'Cite um marco da evolução do design e explique o que ele mudou para o usuário.', 0.1, 'Um marco válido: produção seriada da Revolução Industrial (design passa a planejar produtos em série); tipos móveis/imprensa (design gráfico); chegada dos computadores e da GUI (tela vira objeto de uso comum); Web 1.0 (interface vira documento navegável); era mobile (telas pequenas, toque, design plano e inclusivo).', 'Nota cheia: marco correto + o que mudou para o usuário. Metade: marco certo sem o impacto. Zero: marco inexistente ou fora da aula.'),
      (v_atividade, 2, 2, 'Explique o que a metáfora do escritório físico (janelas, pastas, ícones) ensina para o seu projeto.', 0.2, 'A GUI traduziu o computador em objetos do escritório físico (janelas, pastas, ícones, lixeira), tornando o sistema compreensível sem manual. No agendamento, usar metáforas conhecidas (calendário, cartão de consulta, botão com ícone) reduz o esforço de aprendizado do paciente.', 'Nota cheia: explica a metáfora e aplica ao projeto. Metade: só explica a metáfora. Zero: errado.'),
      (v_atividade, 2, 3, 'Aplique a lição da era mobile (esqueumorfismo → design plano/inclusivo) em uma decisão do agendamento.', 0.2, 'A virada mobile trocou texturas decorativas (esqueumorfismo) por design plano, legível e inclusivo. Aplicação: tela do agendamento com alvos de toque grandes, contraste alto e sem enfeite que atrapalhe o dedo — ex.: botão grande e plano em vez de ícone "realista" pequeno.', 'Nota cheia: decisão concreta ligada à lição mobile/inclusiva. Metade: cita o estilo sem aplicar. Zero: decisão contrária (ex.: adicionar textura pesada).'),
      (v_atividade, 3, 1, 'Indique a forma do botão principal e o que ela comunica ao usuário.', 0.1, 'Botão principal como retângulo arredondado (ou pílula): forma conhecida de área clicável, cantos arredondados passam acolhimento; o retângulo delimita a área de toque.', 'Nota cheia: forma adequada + o que ela comunica. Metade: forma certa sem a leitura. Zero: forma inadequada para botão (ex.: triângulo sem justificativa).'),
      (v_atividade, 3, 2, 'Explique a diferença de leitura entre cantos retos e cantos arredondados nos componentes.', 0.2, 'Cantos retos passam rigidez, formalidade e precisão (uso em painéis técnicos, alertas sérios); cantos arredondados passam amigabilidade e segurança no toque, comuns em botões e cartões de apps.', 'Nota cheia: os dois sentidos contrastados. Metade: só um lado. Zero: inverte ou erra.'),
      (v_atividade, 3, 3, 'Descreva como o peso visual (tamanho, contraste e posição) organiza a hierarquia da sua tela inicial.', 0.2, 'Peso visual: o botão "Agendar" é o maior e mais contrastante da tela (hierarquia 1); o cartão da próxima consulta vem em seguida (hierarquia 2); avisos e rodapé com menos peso. O olhar é guiado do elemento mais pesado para o mais leve.', 'Nota cheia: aplica tamanho + contraste + posição na hierarquia da tela descrita. Metade: só cita os fatores sem aplicar. Zero: sem hierarquia.'),
      (v_atividade, 4, 1, 'Cite uma harmonia do círculo cromático que serviria à paleta do projeto.', 0.1, 'Uma harmonia válida do círculo cromático: análogas (cores vizinhas, suaves), complementares (opostas, contraste forte para destaques) ou monocromática (variações de uma cor). Qualquer uma serve, desde que coerente com a paleta descrita.', 'Nota cheia: harmonia real e aplicável. Metade: nomeia sem saber o que é. Zero: harmonia inexistente.'),
      (v_atividade, 4, 2, 'Explique a regra de contraste entre texto e fundo e por que o cinza-claro sobre branco falha.', 0.2, 'Texto e fundo precisam de contraste suficiente para leitura (relação claro/escuro, mínimos de acessibilidade tipo WCAG). Cinza-claro sobre branco falha porque a diferença de luminância é pequena demais — sob luz solar ou para baixa visão o texto some.', 'Nota cheia: regra do contraste + por que o caso falha. Metade: só a regra ou só o caso. Zero: errado.'),
      (v_atividade, 4, 3, 'Justifique o significado funcional das cores de confirmação e de alerta que você escolheu.', 0.2, 'Verde (ou cor da marca) para confirmação e vermelho para alerta seguem o significado funcional já conhecido pelo usuário (verde = certo/pode seguir; vermelho = perigo/atenção); a cor comunica antes da leitura e precisa vir acompanhada de texto/ícone (não depender só da cor).', 'Nota cheia: significado funcional + aplicação às duas cores. Metade: só uma cor ou sem o "porquê". Zero: escolha sem função.'),
      (v_atividade, 5, 1, 'Separe o relato em fato objetivo, causa técnica provável e efeito prático no usuário.', 0.1, 'Fato objetivo: o usuário não localizou o botão de confirmar (observável). Causa técnica provável: contraste/posição/tamanho do botão ou hierarquia quebrada. Efeito prático: não conclui o agendamento (tarefa falha).', 'Nota cheia: os três separados corretamente. Metade: dois dos três. Zero: trata a reclamação como opinião e para por aí.'),
      (v_atividade, 5, 2, 'Diferencie preferência pessoal ("não gosto da cor") de problema estrutural ("não acho o botão").', 0.2, 'Preferência pessoal é gosto individual sem evidência de falha de uso ("não gosto da cor"). Problema estrutural é verificável e impede/dificulta a tarefa ("não acho o botão" — observável em outros usuários, reproduzível).', 'Nota cheia: distinção + o critério de verificação. Metade: distinção vaga. Zero: trata os dois como iguais.'),
      (v_atividade, 5, 3, 'Escreva o início do relatório técnico de melhoria para esse caso (problema, causa, proposta).', 0.2, 'Relatório com problema (usuários não localizam o botão de confirmar), causa (ex.: contraste baixo e posição fora do fluxo de leitura) e proposta (ex.: botão maior, cor de ação, posição no fim do fluxo). Formato livre, desde que os três campos existam.', 'Nota cheia: três campos presentes e coerentes com o caso. Metade: dois campos. Zero: sem estrutura.'),
      (v_atividade, 6, 1, 'Descreva o cenário: quem usa, onde usa, com qual objetivo e em quais condições (luz, pressa, conexão).', 0.1, 'Cenário completo: quem usa (paciente, ex.: adulto comum e idosos), onde (celular, na rua/em casa, ou totem na clínica), objetivo (marcar/remarcar consulta rápido) e condições reais (luz solar, pressa, conexão instável, uma mão só).', 'Nota cheia: quem + onde + objetivo + pelo menos uma condição. Metade: faltando um dos elementos. Zero: cenário genérico sem os elementos.'),
      (v_atividade, 6, 2, 'Liste duas decisões de interface que mudam por causa desse cenário (ex.: tamanho de botão, contraste).', 0.2, 'Duas decisões ligadas ao cenário, ex.: botões e alvos de toque grandes (dedo, pressa); contraste alto para uso sob sol; poucos campos por tela (pressa); funcionar com conexão ruim/estado salvo (conexão instável).', 'Nota cheia: duas decisões ligadas a condições do cenário. Metade: uma decisão ou decisões soltas do cenário. Zero: decisão sem relação.'),
      (v_atividade, 6, 3, 'Explique por que projetar sem conhecer o cenário gera falhas graves no uso.', 0.2, 'Porque a interface é usada num contexto, não num laboratório: sem conhecer luz, pressa, habilidade e conexão do usuário real, o projeto acerta no papel e falha no uso (texto ilegível, alvo pequeno, fluxo longo demais).', 'Nota cheia: liga cenário desconhecido → falha de uso. Metade: resposta genérica ("fica ruim"). Zero: errado.'),
      (v_atividade, 7, 1, 'Defina User Interface e diferencie CLI, GUI, VUI e NUI em uma frase cada.', 0.1, 'UI = ponte de comunicação entre humano e máquina. CLI: comandos digitados em texto; GUI: janelas, ícones e clique; VUI: interação por voz; NUI: gestos e toque direto, intuitivos.', 'Nota cheia: definição de UI + quatro modalidades corretas. Metade: definição certa com uma ou duas modalidades trocadas. Zero: várias erradas.'),
      (v_atividade, 7, 2, 'Escolha a modalidade do totem para um usuário iniciante e justifique pelo esforço de memorização.', 0.2, 'Totem = NUI (toque direto, gestos conhecidos) — menor esforço de memorização para quem nunca usou computador; alternativa defensável: GUI com alvos grandes também é aceitável se justificada. CLI descartada por exigir comandos decorados.', 'Nota cheia: escolha coerente + justificativa pelo esforço de memorização/aprendizado. Metade: escolha certa sem justificativa. Zero: CLI ou escolha sem critério.'),
      (v_atividade, 7, 3, 'Cite uma vantagem e um limite da modalidade escolhida para o totem.', 0.2, 'Vantagem da NUI: interação intuitiva, quase sem treino (toque = apontar). Limite: precisa de tela sensível ao toque, alvos grandes e feedback claro; sem isso o toque erra (ex.: leitora de pessoas com baixa visão precisa de apoio extra).', 'Nota cheia: uma vantagem + um limite reais. Metade: só um dos dois. Zero: vantagem/limite falsos.'),
      (v_atividade, 8, 1, 'Diferencie o padrão F do padrão Z (tipo de página e trajetória do olhar).', 0.1, 'Padrão F: páginas densas de texto — o olhar faz duas faixas horizontais no topo e desce pela esquerda. Padrão Z: páginas simples com ação — o olhar cruza o topo, desce em diagonal e termina no canto inferior direito (onde fica a ação/CTA).', 'Nota cheia: os dois padrões com tipo de página e trajetória. Metade: um padrão certo. Zero: trajetórias erradas.'),
      (v_atividade, 8, 2, 'Diga qual padrão você usaria na tela inicial e onde ficaria o botão "Agendar".', 0.2, 'Padrão Z (pouco texto + ação clara): logotipo no canto superior esquerdo, elemento secundário no topo direito, imagem/frase na diagonal e o botão "Agendar" no canto inferior direito, ponto final do olhar.', 'Nota cheia: padrão Z + botão no fim da trajetória. Metade: Z sem posicionar o botão. Zero: padrão errado para a tela descrita.'),
      (v_atividade, 8, 3, 'Explique como o alinhamento e a grade (grid) sustentam esse padrão na sua tela.', 0.2, 'O alinhamento rigoroso cria linhas invisíveis que ligam os blocos e sustentam a trajetória do olhar; a grade (grid) dá o alicerce para posicionar logo, imagem e botão nos pontos do Z, sem elementos "soltos".', 'Nota cheia: alinhamento como conexão visual + grid posicionando os elementos do padrão. Metade: só um conceito. Zero: errado.'),
      (v_atividade, 9, 1, 'Cite um elemento de hierarquia visual que você aplicaria (tamanho/escala, espaçamento, textura, fonte ou repetição).', 0.1, 'Um elemento válido: tamanho/escala (botão de confirmação maior), espaçamento/respiro (separar blocos), fonte com pesos (título em negrito), textura/contraste ou repetição (mesmo estilo nos botões de ação).', 'Nota cheia: elemento real + onde aplicaria. Metade: cita o elemento sem aplicação. Zero: elemento fora da aula.'),
      (v_atividade, 9, 2, 'Explique como o espaço em branco (respiro) reduz a sobrecarga e agrupa os blocos da tela.', 0.2, 'O espaço em branco separa grupos e deixa a tela "respirar": blocos próximos são lidos como um grupo só, e o respiro reduz a sobrecarga cognitiva — o usuário entende a tela sem esforço.', 'Nota cheia: reduz sobrecarga + agrupa conteúdo. Metade: só um efeito. Zero: "espaço vazio é desperdício".'),
      (v_atividade, 9, 3, 'Mostre como a repetição de padrões (mesma cor e forma nos botões de ação) cria previsibilidade.', 0.2, 'Repetir a mesma cor, forma e estilo em todos os botões de ação ensina o usuário: "o que parece botão, é botão". A previsibilidade faz ele reconhecer a ação em qualquer tela sem reaprender.', 'Nota cheia: repetição → reconhecimento/previsibilidade. Metade: só "fica bonito/consistente". Zero: errado.'),
      (v_atividade, 10, 1, 'Cite um evento do fluxo e o feedback visual que ele precisa disparar.', 0.1, 'Ex.: tocar em "Agendar" (evento de toque/clique) → o botão muda de estado (pressionado) e aparece indicador de carregamento; ou escolher a data → o dia selecionado fica destacado.', 'Nota cheia: evento + feedback visível ligados. Metade: um dos dois. Zero: sem feedback.'),
      (v_atividade, 10, 2, 'Explique por que o botão sem resposta imediata ("botão fantasma") quebra a confiança do usuário.', 0.2, 'O toque sem resposta deixa o usuário sem saber se o sistema registrou o comando: ele repete o toque, acha que travou, gera ansiedade e perde a confiança — por isso todo evento precisa de feedback imediato (mudança de estado, spinner, mensagem).', 'Nota cheia: dúvida/ansiedade/quebra de confiança + necessidade de feedback imediato. Metade: só uma ponta. Zero: culpa o usuário.'),
      (v_atividade, 10, 3, 'Descreva a rota das quatro telas e como o usuário percebe onde está e como voltar.', 0.2, 'Rota: tela inicial → escolha de data → escolha de horário → confirmação → comprovante (ou equivalente em 4 telas); o usuário percebe onde está por título/passos visíveis e volta por botão "voltar" ou etapas numeradas.', 'Nota cheia: fluxo ligado + orientação do usuário (onde está e como voltar). Metade: fluxo sem orientação. Zero: telas desconectadas.'),
      (v_atividade, 11, 1, 'Diferencie UI (elementos visuais da tela) de UX (experiência geral de uso).', 0.1, 'UI são os elementos visuais e interativos da tela (botões, cores, campos, ícones); UX é a experiência geral de uso — como a pessoa se sente e se consegue concluir a tarefa do início ao fim.', 'Nota cheia: distinção correta dos dois. Metade: conceitos vagos ou parcialmente trocados. Zero: inverte.'),
      (v_atividade, 11, 2, 'Explique o que é design centrado no usuário e o papel da empatia técnica nas decisões.', 0.2, 'Design centrado no usuário = projetar a partir das necessidades reais de quem usa, ouvindo e observando o usuário do início ao fim; empatia técnica é se colocar no lugar do usuário para tomar decisões que atendem a ele (não o gosto do designer).', 'Nota cheia: DCU + empatia aplicados. Metade: só um conceito. Zero: "centrado no designer/cliente".'),
      (v_atividade, 11, 3, 'Dê um exemplo de decisão do agendamento que muda quando se ouve o paciente.', 0.2, 'Exemplo concreto: aumentar a letra e os botões após ouvir pacientes idosos; trocar o termo "agendamento" por "marcar consulta"; trazer a confirmação para menos toques; adicionar modo de alto contraste. Qualquer decisão ligada a uma necessidade observada vale.', 'Nota cheia: decisão ligada a necessidade do paciente. Metade: decisão genérica sem o vínculo. Zero: decisão estética sem usuário.'),
      (v_atividade, 12, 1, 'Liste as quatro etapas do ciclo de design iterativo (entender, criar, testar, melhorar).', 0.1, 'Entender (o problema e o usuário) → criar (proposta/protótipo) → testar (com usuários) → melhorar (ajustar e repetir o ciclo).', 'Nota cheia: quatro etapas na ordem. Metade: etapas certas fora de ordem ou faltando uma. Zero: etapas erradas.'),
      (v_atividade, 12, 2, 'Explique por que a versão 2 deve ser orientada pelas evidências do teste, e não por opiniões.', 0.2, 'Porque a evidência do teste mostra o que realmente falha no uso (três não acharam o botão, dois pediram letra maior); mudar por opinião seria palpite — a V2 existe para corrigir o que os testes provaram.', 'Nota cheia: evidência como base da melhoria. Metade: "porque teste é importante" sem ligar à V2. Zero: defende mudar por gosto.'),
      (v_atividade, 12, 3, 'Registre duas melhorias objetivas da V1 para a V2 ligadas às evidências do caso.', 0.2, 'Duas melhorias ligadas às evidências: ex.: botão de confirmar maior/com cor de ação e no fim do fluxo (evidência: não achado) e aumento do tamanho da fonte (evidência: pedido de letra maior). Aceito equivalentes que respondam às duas observações.', 'Nota cheia: duas melhorias rastreáveis às evidências. Metade: uma melhoria ou melhorias sem vínculo. Zero: mudanças alheias ao teste.'),
      (v_atividade, 13, 1, 'Identifique o público-alvo do agendamento e seu objetivo primário.', 0.1, 'Público-alvo: pacientes da clínica (todas as idades, inclusive idosos/iniciantes digitais); objetivo primário: marcar consulta sem precisar ligar para a recepção (rápido e sem ajuda).', 'Nota cheia: quem + objetivo primário. Metade: só um. Zero: público vago ("todo mundo").'),
      (v_atividade, 13, 2, 'Liste as etapas da jornada (descobrir o serviço → abrir o app → escolher data → confirmar → comprovante) e aponte o ponto de atrito.', 0.2, 'Jornada com etapas coerentes (descobrir → abrir app → dados/login → escolher data → confirmar → comprovante) e o atrito localizado na tela de dados pessoais (desistência concentrada ali = pede dados demais/campo confuso).', 'Nota cheia: etapas + atrito identificado na tela certa. Metade: etapas sem localizar o atrito. Zero: sem jornada.'),
      (v_atividade, 13, 3, 'Escreva uma pergunta neutra de entrevista para investigar esse ponto de atrito.', 0.2, 'Pergunta neutra: aberta, sem induzir resposta e sem julgamento — ex.: "O que você achou da tela de dados pessoais?" ou "Como foi preencher essa tela?". Inválidas: "Não achou a tela confusa?", "Concorda que pede dados demais?".', 'Nota cheia: pergunta aberta e neutra sobre o ponto de atrito. Metade: pergunta aberta mas vaga/ampla demais. Zero: pergunta induzida ou fechada de sim/não.'),
      (v_atividade, 14, 1, 'Cite os três aspectos da usabilidade (eficácia, eficiência e satisfação) com um exemplo na tela.', 0.1, 'Eficácia (consegue concluir a confirmação?), eficiência (com quanto esforço/tempo?) e satisfação (como se sente usando?). Ex.: paciente confirma a consulta em poucos toques sem erro e sem ajuda.', 'Nota cheia: três aspectos + exemplo na tela. Metade: três aspectos sem exemplo ou dois com exemplo. Zero: menos de dois.'),
      (v_atividade, 14, 2, 'Explique o que torna uma interface intuitiva (modelo mental e affordance) com um exemplo seu.', 0.2, 'Intuitiva = o usuário antecipa a ação certa sem manual porque a tela segue o modelo mental dele; affordance = a forma do elemento "ensina" o uso (botão parece clicável, campo parece editável). Ex.: botão grande com rótulo "Agendar" que se parece com botão.', 'Nota cheia: modelo mental/affordance + exemplo. Metade: conceito sem exemplo. Zero: errado.'),
      (v_atividade, 14, 3, 'Diga de quem é a culpa quando o usuário se perde na tela, e o que isso muda na correção.', 0.2, 'A culpa é do design, não do usuário (exemplo da porta com puxador errado): quando alguém se perde, a tela não comunicou o caminho. Correção: consertar a interface (affordance, rótulos, fluxo), não "treinar" o usuário para tolerar a falha.', 'Nota cheia: culpa no design + correção na interface. Metade: só "é do design" sem a consequência. Zero: culpa o usuário.'),
      (v_atividade, 15, 1, 'Diferencie questionário estruturado de entrevista em profundidade (alcance × profundidade).', 0.1, 'Questionário estruturado: perguntas fechadas/padronizadas para muitas pessoas, gera métricas objetivas e rápido alcance. Entrevista em profundidade: conversa com poucos, revela motivações, sentimentos e dores reais.', 'Nota cheia: as duas com a diferença alcance × profundidade. Metade: as duas sem a diferença. Zero: troca os conceitos.'),
      (v_atividade, 15, 2, 'Indique qual estratégia responde "quantos travam" e qual responde "por que desistem", justificando.', 0.2, '"Quantos travam" → questionário/métrica (escala, número de desistências). "Por que desistem" → entrevista em profundidade (motivação, sentimento). Justificativa: quantidade se mede em massa; motivo se explora em conversa.', 'Nota cheia: estratégia certa para cada pergunta + justificativa. Metade: escolha certa sem justificativa. Zero: estratégias invertidas.'),
      (v_atividade, 15, 3, 'Explique como os dados coletados deixam de ser palpite e viram decisão de design.', 0.2, 'Dados reais substituem o palpite: em vez de "eu acho", a equipe decide com evidência (ex.: 60% desistem na tela de dados → simplificar essa tela vira prioridade). O dado aponta onde mexer e permite medir se melhorou.', 'Nota cheia: dado → decisão de design no caso. Metade: genérico ("dados ajudam"). Zero: defende o palpite.'),
      (v_atividade, 16, 1, 'Explique por que ouvir feedbacks não significa implementar tudo o que foi pedido.', 0.1, 'Porque feedback é insumo, não ordem: pedidos podem se contradizer, vir de casos isolados ou sair do escopo; ouvir registra a necessidade, mas implementar exige critério (objetivo do sistema, evidência, prioridade).', 'Nota cheia: ouvir ≠ implementar, com razão. Metade: ideia certa mal explicada. Zero: "implementa tudo" ou "ignora tudo".'),
      (v_atividade, 16, 2, 'Proponha uma mediação que atenda a necessidade real dos dois lados na tela inicial.', 0.2, 'Mediação possível: tela inicial limpa com o essencial (próxima consulta + botão agendar) e os detalhes a um toque de distância (cartão expansível ou tela de detalhes) — atende quem quer informação sem poluir para quem quer simplicidade.', 'Nota cheia: solução intermediária coerente que atende aos dois lados. Metade: solução que favorece um lado com alguma justificativa. Zero: escolhe um lado ignorando o outro sem critério.'),
      (v_atividade, 16, 3, 'Justifique a sua decisão com um critério técnico (objetivo do usuário, atrito medido ou prioridade).', 0.2, 'Critério técnico explícito: ex., o objetivo primário (agendar rápido) manda na tela inicial; ou o atrito medido (desistências) define a prioridade; ou a necessidade mais frequente na coleta vence o pedido isolado.', 'Nota cheia: critério técnico nomeado e aplicado à decisão. Metade: critério genérico. Zero: decisão sem critério.'),
      (v_atividade, 17, 1, 'Defina escopo e fronteira do projeto em uma frase cada.', 0.1, 'Escopo: o conjunto total de entregas, funções e telas planejadas para o projeto. Fronteira: o limite exato que separa o que faz parte do sistema daquilo que fica fora dele nesta versão.', 'Nota cheia: duas definições corretas. Metade: uma correta. Zero: erradas.'),
      (v_atividade, 17, 2, 'Liste o que entra e o que fica fora da versão 1, com prioridade no que resolve a dor central (agendar sem ligar).', 0.2, 'Entra na V1: marcar, remarcar e cancelar consulta com confirmação e comprovante (a dor central). Fica fora: chat, pagamento online e histórico de exames (secundários, não resolvem a dor inicial). Lista equivalente com a mesma lógica vale.', 'Nota cheia: dentro/fora coerente + prioridade na dor central. Metade: lista sem o critério de prioridade. Zero: inclui tudo na V1.'),
      (v_atividade, 17, 3, 'Explique como dizer "não" aos pedidos secundários protege o prazo e o foco do projeto.', 0.2, 'Dizer "não" aos secundários evita o inchaço do projeto (scope creep): a equipe entrega o essencial no prazo, testa com usuários e só depois expande; tentar tudo de uma vez atrasa e dilui o foco no que resolve a dor.', 'Nota cheia: proteção de prazo/foco + lógica de versões. Metade: só "economiza tempo". Zero: defende incluir tudo.'),
      (v_atividade, 18, 1, 'Explique o que é um storyboard e o que ele representa na prototipagem.', 0.1, 'Storyboard: sequência de quadros que narra a jornada do usuário em contexto real (quem, onde, o que sente e faz) antes do desenho técnico das telas — mostra a situação de uso, não a interface.', 'Nota cheia: quadros + jornada em contexto real + antes do desenho. Metade: só "sequência de desenhos". Zero: confunde com fluxo de telas.'),
      (v_atividade, 18, 2, 'Descreva três quadros do storyboard da Dona Marta (situação, uso do app, resultado).', 0.2, 'Três quadros coerentes, ex.: 1) Dona Marta em casa lembra da consulta e pega o celular; 2) ela abre o app e toca em "Agendar" com letra grande; 3) ela vê a confirmação na tela e fica tranquila. Situação → uso → resultado, com contexto real.', 'Nota cheia: três quadros com situação/uso/resultado. Metade: quadros sem contexto ou sem fechamento. Zero: telas descritas sem narrativa.'),
      (v_atividade, 18, 3, 'Diga o que o storyboard revela para o design que uma lista de requisitos não mostra.', 0.2, 'O storyboard revela contexto e emoção que a lista de requisitos não mostra: ambiente (sofá, óculos, pressa), estado emocional (ansiedade → alívio) e o porquê de cada tela existir — guiando decisões como tamanho de letra e simplicidade.', 'Nota cheia: contexto/emoção guiando decisão de design. Metade: só "mostra a história". Zero: errado.'),
      (v_atividade, 19, 1, 'Diferencie protótipo de papel, mock-up de média fidelidade e mock-up de alta fidelidade.', 0.1, 'Protótipo de papel: rascunho de baixa fidelidade para testar fluxos (rápido e barato). Mock-up de média fidelidade: tela digital com estrutura e conteúdo, ainda sem acabamento final. Alta fidelidade: representação visual fiel (cores, fontes, imagens, espaçamento definitivos).', 'Nota cheia: três níveis diferenciados. Metade: dois. Zero: um ou invertidos.'),
      (v_atividade, 19, 2, 'Explique por que os testes de usabilidade vêm no papel e não no mock-up final.', 0.2, 'Porque no papel o teste é rápido, barato e fácil de refazer: descobre falhas de fluxo e navegação em minutos, antes de gastar tempo com fidelidade — corrigir o fluxo depois do mock-up (ou pior, do código) custa caro.', 'Nota cheia: rapidez/custo + correção de fluxo antes da fidelidade. Metade: só "é mais barato". Zero: errado.'),
      (v_atividade, 19, 3, 'Cite o que o mock-up de alta fidelidade define para a codificação (cores, fontes, componentes, espaçamento).', 0.2, 'O mock-up de alta fidelidade define para a codificação: cores e contraste finais, tipografia (fontes e tamanhos), espaçamentos, componentes reutilizáveis e o acabamento visual exato de cada tela — a referência visual do front-end.', 'Nota cheia: pelo menos três definições ligadas ao handoff de codificação. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 20, 1, 'Explique por que "estar no Google" não significa "pode usar" (direito autoral e anterioridade).', 0.1, 'Porque publicar na internet não concede licença: toda imagem/fonte/ícone tem autor, e o direito autoral protege a obra desde a criação; a anterioridade prova quem criou primeiro. Usar sem licença pode gerar notificação extrajudicial, multa e obrigação de tirar do ar.', 'Nota cheia: autoria protegida + consequência do uso indevido. Metade: só "tem dono". Zero: acha que pode usar.'),
      (v_atividade, 20, 2, 'Descreva o que uma licença Creative Commons informa e como você checaria a licença de cada recurso.', 0.2, 'A licença Creative Commons informa o que o autor permite: uso comercial ou não, alteração permitida, obrigação de dar crédito (atribuição), compartilhamento pela mesma licença. Conferência: verificar a licença na página/fonte de cada recurso (site do autor, repositório com licença, ex.: Font Awesome, Google Fonts, Unsplash) e registrar a licença de cada item usado.', 'Nota cheia: o que a licença informa + como conferir cada recurso. Metade: só um lado. Zero: errado.'),
      (v_atividade, 20, 3, 'Diga o que você faria com a foto sem licença clara e por que o registro/documentação do processo protege o projeto.', 0.2, 'Com a foto sem licença clara: substituir por uma de banco com licença aberta (CC ou domínio público) ou pedir autorização ao autor — nunca usar assim mesmo. Documentar o processo e registrar a autoria protege o projeto (prova de criação e data) e evita problemas legais.', 'Nota cheia: atitude correta (trocar/autorizar) + valor do registro/documentação. Metade: só a atitude. Zero: manter a foto sem licença.');
end $$;
